import pandas as pd, collections
df = pd.read_csv('dataset/hospital_compensation_registry.csv')
byid = df.set_index('patient_id')
# undirected adjacency
adj=collections.defaultdict(set)
for _,r in df.iterrows():
    ec=r['emergency_contact_patient_id']
    if pd.notna(ec) and ec in byid.index:
        adj[r['patient_id']].add(ec); adj[ec].add(r['patient_id'])

def bfs(src):
    dist={src:0}; q=[src]
    while q:
        nq=[]
        for u in q:
            for v in adj[u]:
                if v not in dist: dist[v]=dist[u]+1; nq.append(v)
        q=nq
    return dist

for surname,filer in [('Quill','PAT_265'),('Rivera','PAT_033'),('Jones','PAT_006')]:
    d=bfs(filer)
    fam=df[(df['second_name']==surname)&(df['patient_id']!=filer)]
    print(f'=== {surname} family, distance to filer {filer} ===')
    recs=[]
    for _,r in fam.iterrows():
        recs.append((d.get(r['patient_id'],99), r['patient_id'], r['full_name'], 'NOCLAIM' if pd.isna(r['record_date']) else r['compensation_reason']))
    for dd,pid,name,cl in sorted(recs):
        print(f'  dist={dd}  {pid} {name:16} {cl}')
    print()
"

